53	// Pass the command line arguments to v8.
54	// Returns a vector of command line arguments that v8 did not understand.
55	fn set_flags(args: Vec<String>) -> Vec<String> {
56	  // deno_set_flags(int* argc, char** argv) mutates argc and argv to remove
57	  // flags that v8 understands.
58	  // First parse core args, then converto to a vector of C strings.
59	  let (argv, rest) = parse_core_args(args);
60	  let mut argv = argv
61	    .iter()
62	    .map(|arg| CString::new(arg.as_str()).unwrap().into_bytes_with_nul())
63	    .collect::<Vec<_>>();
64	
65	  // Make a new array, that can be modified by V8::SetFlagsFromCommandLine(),
66	  // containing mutable raw pointers to the individual command line args.
67	  let mut c_argv = argv
68	    .iter_mut()
69	    .map(|arg| arg.as_mut_ptr() as *mut i8)
70	    .collect::<Vec<_>>();
71	  // Store the length of the argv array in a local variable. We'll pass a
72	  // pointer to this local variable to deno_set_flags(), which then
73	  // updates its value.
74	  let mut c_argc = c_argv.len() as c_int;
75	  // Let v8 parse the arguments it recognizes and remove them from c_argv.
76	  unsafe {
77	    binding::deno_set_flags(&mut c_argc, c_argv.as_mut_ptr());
78	  };
79	  // If c_argc was updated we have to change the length of c_argv to match.
80	  c_argv.truncate(c_argc as usize);
81	  // Copy the modified arguments list into a proper rust vec and return it.
82	  c_argv
83	    .iter()
84	    .map(|ptr| unsafe {
85	      let cstr = CStr::from_ptr(*ptr as *const i8);
86	      let slice = cstr.to_str().unwrap();
87	      slice.to_string()
88	    })
89	    .chain(rest.into_iter())
90	    .collect()
91	}
