// Parses flags for deno.
// This is very specialized to the needs of deno and could be replaced by a
// proper CLI parsing library in the future. It separates the recognized flags
// from the remaining arguments, which are returned as the second tuple element.
pub fn set_flags(args: Vec<String>) -> (DenoFlags, Vec<String>) {
  let mut flags = DenoFlags::default();
  let mut rest = Vec::new();

  for arg in args {
    match arg.as_str() {
      "-h" | "--help" => flags.help = true,
      "-D" | "--log-debug" => flags.log_debug = true,
      "-v" | "--version" => flags.version = true,
      "-r" | "--reload" => flags.reload = true,
      "--allow-write" => flags.allow_write = true,
      "--allow-net" => flags.allow_net = true,
      _ => rest.push(arg),
    }
  }

  (flags, rest)
}

#[test]
fn test_set_flags_1() {
  let (flags, rest) = set_flags(svec!["deno", "--version"]);
  assert_eq!(rest, svec!["deno"]);
  assert_eq!(
    flags,
    DenoFlags {
      version: true,
      ..DenoFlags::default()
    }
  );
}

